fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // k is 1-based index, convert to 0-based index
    let zero_based = k - 1; 

    // Create a new vector with capacity n-1
    let mut new_list = Vec::with_capacity(list.len() - 1);

    // Extend with elements before the k-th element
    new_list.extend_from_slice(&list[0..zero_based]);

    // Extend with elements after the k-th element
    new_list.extend_from_slice(&list[zero_based + 1..]);

    new_list
}